const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || message.text || payload.text || '').trim();
const fileId = source.fileId || payload.fileId || '';
let fileName = String(source.fileName || payload.fileName || '').trim();
let newName = String(source.newName || payload.newName || '').trim();
const targetFolderId = source.targetFolderId || payload.targetFolderId || '';
const cleaned = raw.replace(/^(copy file|nhan ban file|tao ban sao file|duplicate file|copy template)\s*/i, '').trim();
if (!fileName) { const m = cleaned.match(/^(.*?)\s+(?:thanh|to)\s+(.*)$/i); if (m) { fileName = m[1].trim(); if (!newName) newName = m[2].trim(); } else { fileName = cleaned; } }
return [{ json: { ...source, payload, message, chatId, raw, fileId, fileName, newName, targetFolderId, hasTarget: Boolean(fileId || fileName), response: (fileId || fileName) ? '' : '📄 <b>Copy file</b>\n\nVi du: copy file mau hop dong thanh hop dong khach A' } }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');
const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};
const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const source = $('Prepare Action').item.json;
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) return [{ json: { ...source, found: false, response: 'Khong tim thay file phu hop.' } }];
const file = rows[0];
return [{ json: { ...source, found: true, fileId: file.id, fileName: file.name || source.fileName || '', webViewLink: file.webViewLink || '', mimeType: file.mimeType || '', modifiedTime: file.modifiedTime || '' } }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};

const fileName =
  item.name ||
  source.newName ||
  source.fileName ||
  source.targetName ||
  'Không rõ tên';

const fileId =
  item.id ||
  item.fileId ||
  source.newFileId ||
  source.fileId ||
  source.targetId ||
  '';

const link =
  item.webViewLink ||
  item.webContentLink ||
  (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

const mimeType =
  item.mimeType ||
  source.mimeType ||
  '';

let text = '✅ <b>Đã copy file</b>\n\n';

text += `📄 <b>${escapeHtml(fileName)}</b>\n`;

if (mimeType) {
  text += `Loại: <code>${escapeHtml(mimeType)}</code>\n`;
}

if (fileId) {
  text += `ID: <code>${escapeHtml(fileId)}</code>\n`;
}

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>\n`;
}

return [{
  json: {
    chatId: source.chatId || item.chatId,
    text: text.trim(),
  },
}];
